// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertDoesNotThrow;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.mockito.Mockito.mock;

import java.lang.reflect.Field;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Set;
import java.util.concurrent.atomic.AtomicLong;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.algebra.Join;
import org.eclipse.rdf4j.query.algebra.StatementPattern;
import org.eclipse.rdf4j.query.algebra.Var;
import org.eclipse.rdf4j.query.algebra.evaluation.optimizer.PatternKey;
import org.eclipse.rdf4j.query.explanation.TelemetryMetricNames;
import org.eclipse.rdf4j.sail.lmdb.sketch.SketchSnapshotIdentity;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * A committed statement-mutation stamp that moves backwards means the learned sidecars no longer describe the live
 * store (the store was rebuilt, restored from a backup or its journal was reset). That is a reason to drop the learned
 * state and adopt the live coordinate, never a reason to throw out of the post-commit hook: the hook runs after the
 * triple and value stores are durable, so an exception there would surface as a failed commit for data that was in fact
 * persisted (review finding 3.7.5 (b)). A negative stamp remains a programming error and still throws.
 */
class LmdbMutationStampRegressionTest {

	private static final SketchSnapshotIdentity IDENTITY = new SketchSnapshotIdentity(0x1234L, 0x5678L, 9L);
	private static final ValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI P1 = VF.createIRI("urn:test:stamp-regression:p1");
	private static final IRI P2 = VF.createIRI("urn:test:stamp-regression:p2");

	@Test
	void operatorFeedbackStatsResetAndAdoptARegressedStamp(@TempDir Path tempDir) throws Exception {
		AtomicLong liveStamp = new AtomicLong(42L);
		LmdbOperatorFeedbackStats stats = new LmdbOperatorFeedbackStats(estimatorPath(tempDir), () -> IDENTITY,
				() -> true, liveStamp::get);
		learnMultiplier(stats);
		assertNotNull(stats.estimate(join(), 200.0d, 100.0d, 10.0d, 20.0d),
				"precondition: the learned multiplier is served before the regression");

		assertDoesNotThrow(() -> stats.recordStoreMutation(41L, Set.of()),
				"a regressed stamp is a store-identity change, not a programming error");
		assertEquals(41L, appliedStamp(stats), "the live (regressed) coordinate must be adopted");
		assertNull(stats.estimate(join(), 200.0d, 100.0d, 10.0d, 20.0d),
				"learned evidence stamped for a different store identity must be dropped (fail toward no evidence)");

		learnMultiplier(stats);
		assertNotNull(stats.estimate(join(), 200.0d, 100.0d, 10.0d, 20.0d),
				"learning must resume at the adopted coordinate");
		assertDoesNotThrow(() -> stats.recordStoreMutation(41L, Set.of()), "same-stamp commits stay accepted");
		assertDoesNotThrow(() -> stats.recordStoreMutation(43L, Set.of()), "forward commits stay accepted");
		assertEquals(43L, appliedStamp(stats));

		assertThrows(IllegalArgumentException.class, () -> stats.recordStoreMutation(-1L, Set.of()),
				"a negative stamp is still a programming error");
	}

	@Test
	void filterSelectivityStatsResetAndAdoptARegressedStamp(@TempDir Path tempDir) throws Exception {
		Path estimatorPath = tempDir.resolve("join-estimator.rjes");
		LmdbFilterSelectivityStats stats = new LmdbFilterSelectivityStats(estimatorPath, mock(TripleStore.class),
				mock(ValueStore.class), false, 0L, 0, false, () -> IDENTITY, 0, () -> true, () -> 5L);
		PatternKey key = new PatternKey(VF.createIRI("urn:test:stamp-regression:predicate"), 0);
		stats.recordFilterOutcome(key, "BOUND(?value)", 1L, 1L);
		assertTrue(stats.getFilterPassRatio(key, "BOUND(?value)") >= 0.0d,
				"precondition: the filter cell is served before the regression");

		assertDoesNotThrow(() -> stats.recordStoreMutation(4L),
				"a regressed stamp is a store-identity change, not a programming error");
		assertEquals(4L, appliedStamp(stats), "the live (regressed) coordinate must be adopted");
		assertEquals(-1.0d, stats.getFilterPassRatio(key, "BOUND(?value)"), 0.0d,
				"learned filter cells stamped for a different store identity must be dropped");

		assertDoesNotThrow(() -> stats.recordStoreMutation(4L), "same-stamp commits stay accepted");
		assertDoesNotThrow(() -> stats.recordStoreMutation(6L), "forward commits stay accepted");
		assertEquals(6L, appliedStamp(stats));

		assertThrows(IllegalArgumentException.class, () -> stats.recordStoreMutation(-1L),
				"a negative stamp is still a programming error");
		assertThrows(IllegalArgumentException.class,
				() -> new LmdbFilterSelectivityStats(estimatorPath, mock(TripleStore.class), mock(ValueStore.class),
						false, 0L, 0, false, () -> null, 0, () -> true, () -> -1L),
				"a negative live stamp at construction is still a programming error");
	}

	private static void learnMultiplier(LmdbOperatorFeedbackStats stats) {
		Join observed = join();
		observed.setRuntimeTelemetryEnabled(true);
		observed.setResultSizeEstimate(10.0d);
		observed.setCostEstimate(20.0d);
		observed.setDoubleMetricPlanned(TelemetryMetricNames.PLANNED_WORK_ROWS, 20.0d);
		observed.setResultSizeActual(100L);
		observed.setLongMetricActual(TelemetryMetricNames.OUTPUT_ROWS_ACTUAL, 100L);
		observed.setLongMetricActual(TelemetryMetricNames.CLOSE_COUNT_ACTUAL, 1L);
		observed.setLongMetricActual(TelemetryMetricNames.EXHAUSTED_CLOSE_COUNT_ACTUAL, 1L);
		observed.setHasNextCallCountActual(101L);
		observed.setHasNextTrueCountActual(100L);
		observed.setJoinLeftBindingsConsumedActual(50L);
		observed.setJoinRightBindingsConsumedActual(100L);
		stats.recordOperatorOutcome(observed);
	}

	private static Join join() {
		return new Join(
				new StatementPattern(Var.of("s"), Var.of("_p1", P1, true, true), Var.of("x")),
				new StatementPattern(Var.of("x"), Var.of("_p2", P2, true, true), Var.of("o")));
	}

	private static Path estimatorPath(Path tempDir) throws Exception {
		Path estimatorPath = tempDir.resolve("join-estimator.rjes");
		Files.createDirectories(estimatorPath);
		Files.writeString(estimatorPath.resolve("metadata.bin"), "metadata");
		return estimatorPath;
	}

	private static long appliedStamp(Object stats) throws Exception {
		Field field = stats.getClass().getDeclaredField("appliedStatementMutationStamp");
		field.setAccessible(true);
		return field.getLong(stats);
	}
}
